from .state import CI



def _stolen(s, v):
    """A stolen declared shot, relative to banked: the shot is cancelled and the carrier keeps the ball (his
    look v), less the turnover cost; in the final phase the possession scores 0 (resolve.pickoff_value)."""
    from .resolve import pickoff_value
    return pickoff_value(s, v, relative=True)

class Timeout(Exception):
    pass


# =====================================================================================
# values
# =====================================================================================

@dataclass(frozen=True)
class Val:
    """Expected possession score, expected look, P(look >= 30), P(clock reaches 0),
    expected forced-shot points (counted only when the clock expires)."""
    ev: float
    look: float = 0.0
    p30: float = 0.0
    pexp: float = 0.0
    fs: float = 0.0


def mix(pairs):
    """Weighted average of Val tuples: pairs = [(p, (Val, ...)), ...]."""
    n = len(pairs[0][1])
    out = []
    for t in range(n):
        ev = look = p30 = pexp = fs = 0.0
        for p, vs in pairs:
            v = vs[t]
            ev += p * v.ev
            look += p * v.look
            p30 += p * v.p30
            pexp += p * v.pexp
            fs += p * v.fs
        out.append(Val(ev, look, p30, pexp, fs))
    return tuple(out)


def terminal_vals(s, targets):
    out = []
    for t in targets:
        st = s if t is None else s.with_(target=t)
        sc = score(st)
        r = s.result
        shot = r is not None and r.kind in ('shot', 'forced', 'free_throws')
        look = float(sc.look) if shot else 0.0
        expired = s.clock == 0
        out.append(Val(float(sc.total), look, 1.0 if (shot and sc.look >= RC.SCENARIO_GOAL and not s.zeroed) else 0.0,
